WITH benchmark AS (SELECT pct_change AS benchmark FROM `findsl_ext`.`index_quote` WHERE index_code='000300' AND snapshot_id='akshare-sina-index-2026-07-15-42e29790031f' AND bizdate='2026-04-14'), ranked AS (SELECT q.mktcode,q.tgtcode,q.bizdate,((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0)) AS pct_change,ROW_NUMBER() OVER (ORDER BY ((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0)) DESC,q.mktcode ASC,q.tgtcode ASC) AS rn FROM `newzl`.`hsj_stock_hq_basic` q WHERE q.bizdate='2026-04-14' AND q.mktcode IN (0,1,103) AND EXISTS (SELECT 1 FROM `findsl_ext`.`scope_membership` s WHERE s.mktcode=q.mktcode AND s.tgtcode=q.tgtcode AND s.scope_code='BK0800' AND s.snapshot_id='curated-scope-alias-2026-07-30-7a4260479631')) SELECT r.mktcode,r.tgtcode,r.bizdate FROM ranked r CROSS JOIN benchmark b WHERE r.rn=1 AND r.pct_change<=b.benchmark;
